		{
			return;
		}
		int type, type2;
		if (r >= 0) type = 10;
		else type = 8;
		if (r >= 0) type2 = 4;
		else type2 = 2;
		shot(5, bossX + r * cos(angle), bossY + r * sin(angle), 0, 0, type, 0);
		shot(5, bossX + r * cos(angle + 1.57), bossY + r * sin(angle + 1.57), 0, 0, type2, 0);
		shot(5, bossX + r * cos(angle + 3.14), bossY + r * sin(angle + 3.14), 0, 0, type, 0);
		shot(5, bossX + r * cos(angle + 4.71), bossY + r * sin(angle + 4.71), 0, 0, type2, 0);
