void typhoon()
{
	DWORD tab;
	int bossX, bossY, myX, myY, bulletX, bulletY = 0;
	ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0x8 + 0x14C * bossId), &bossX, 4, 0);
	ReadProcessMemory(hProcess, (LPVOID)(plantsStart + 0xC + 0x14C * bossId), &bossY, 4, 0);
	float r = 0, flag, dx, dy, rr = 0;
	int t = 0;
	while (1)
	{
		ReadProcessMemory(hProcess, (LPVOID)(addr + 0x5610), &tab, 4, 0);
		if (tab == 0)
		{
			return;
		}
		ReadProcessMemory(hProcess, (LPVOID)(zombiesStart + 0x8 + 0x15C * myId), &myX, 4, 0);
		ReadProcessMemory(hProcess, (LPVOID)(zombiesStart + 0xC + 0x15C * myId), &myY, 4, 0);
		myX += 50; myY += 40;
		rr += 0.174;
		for (int i = 0; i < 3; i++)
		{
			bulletX = bossX + 400 * cos(i*2.09 + rr);
			bulletY = bossY + 400 * sin(i*2.09 + rr);
			r = atan(((float)bossY - (float)bulletY) / ((float)bossX - (float)bulletX));
			if (bulletX > bossY) flag = -1;
			else flag = 1;
			dx = 3 * cos(r) * flag;
			dy = 3 * sin(r) * flag;
			shot(5, bulletX, bulletY, dx, dy, randBigStar(), 0);
		}
		if (t == 2)
		{
			t = 0;
			for (int i = 0; i < 6; i++)
			{
				bulletX = bossX + 100 * cos(i*1.0466);
				bulletY = bossY + 100 * sin(i*1.0466);
				r = atan(((float)myY - (float)bulletY) / ((float)myX - (float)bulletX));
				if (bulletX > myX) flag = -1;
				else flag = 1;
				dx = 3 * cos(r) * flag;
				dy = 3 * sin(r) * flag;
				shot(5, bulletX, bulletY, dx, dy, randStar(), 0);
			}
		}
		t++;
		Sleep(500);
	}
}
